INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l38','come into being','',NULL,'/kʌm ˈɪntə ˈbiːɪŋ/','Calendars came into being long ago.','历法很久以前就出现了。','A new nation came into being.','一个新的国家诞生了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l38','rely on','',NULL,'/rɪˈlaɪ ɑːn/','They will not rely solely on the written word.','他们不会只依赖文字。','You can rely on me.','你可以信赖我。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l38','shed light on','',NULL,'/ʃed laɪt ɑːn/','These remains shed light on early man.','这些遗存让我们更了解早期人类。','The study sheds light on the problem.','这项研究有助于弄清这个问题。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l38','up to now','',NULL,'/ʌp tə naʊ/','Up to now, historians have assumed this.','到目前为止,历史学家一直这么假定。','Up to now, no one has complained.','到目前为止,没人抱怨过。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp1','choice','{"stem":"\"The dots have ___ engraved on bones and ivory.\"(现在完成时的被动,填 have 和过去分词中间的那个词)","options":["been","was","being","be"],"answer_index":0,"stem_cn":"这些小圆点被刻在骨头和象牙上。","explanation_cn":"现在完成时的被动 have been + 过去分词。✓ The dots have been engraved on bones. ✗ being / be / was:现在完成被动用 been + 过去分词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp1','choice','{"stem":"\"Historians have long been ___ by these strange markings.\"(have been + 过去分词\"一直被…\")","options":["to puzzle","puzzled","puzzle","puzzling"],"answer_index":1,"stem_cn":"历史学家长期被这些奇怪的记号搞糊涂。","explanation_cn":"have been + 过去分词,“一直被(弄糊涂)”。✓ have long been puzzled by these markings. ✗ puzzling(主动)/ puzzle / to puzzle:被动用过去分词 puzzled。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp1','choice','{"stem":"\"It has long been ___ that the cave paintings had a meaning.\"(It has long been + 过去分词\"早已被…\")","options":["know","to know","known","knowing"],"answer_index":2,"stem_cn":"人们早就知道那些洞穴壁画是有含义的。","explanation_cn":"It has long been + 过去分词,“早已被(知道)”。✓ It has long been known that… ✗ knowing(主动)/ know / to know:被动用过去分词 known。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp2','choice','{"stem":"\"Early man ___ faced with a real need to understand the seasons.\"(一般过去时的被动,主语单数,填助动词)","options":["was","is","being","has been"],"answer_index":0,"stem_cn":"早期人类当时面临真正需要了解季节的问题。","explanation_cn":"一般过去时的被动 was + 过去分词;主语单数用 was。✓ Early man was faced with a real need. ✗ is(现在)/ has been(完成)/ being:过去被动用 was。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp2','choice','{"stem":"\"These markings ___ made during the last Ice Age.\"(一般过去被动,主语是复数)","options":["was","are","being","were"],"answer_index":3,"stem_cn":"这些记号是在上一个冰河时代做的。","explanation_cn":"一般过去时的被动,主语是复数(these markings)用 were。✓ these markings were made. ✗ was(单数)/ are(现在)/ being:复数过去被动用 were。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp2','choice','{"stem":"\"The code ___ finally read by correlating markings worldwide.\"(一般过去时的被动,主语单数,填助动词)","options":["has","being","was","is"],"answer_index":2,"stem_cn":"这套密码最终通过比对世界各地的记号被解读了。","explanation_cn":"一般过去时的被动 was + 过去分词。✓ The code was finally read. ✗ is(现在)/ has(完成)/ being:过去被动用 was。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp3','choice','{"stem":"\"The historian is faced ___ a very difficult task.\"(be faced ___ 用哪个介词)","options":["to","for","of","with"],"answer_index":3,"stem_cn":"历史学家面对着一项极难的任务。","explanation_cn":"be faced with sth,“面对…”,固定介词 with。✓ faced with a difficult task. ✗ for / of / to:faced 搭配 with。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp3','choice','{"stem":"\"The markings are connected ___ the phases of the moon.\"(be connected ___ 用哪个介词)","options":["with","off","for","about"],"answer_index":0,"stem_cn":"这些记号与月相有关。","explanation_cn":"be connected with sth,“与…有关”,固定介词 with。✓ connected with the phases of the moon. ✗ for / about / off:connected 搭配 with。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp3','choice','{"stem":"\"These clues can account ___ the strange dots.\"(account ___,\"解释\"用哪个介词)","options":["of","for","with","at"],"answer_index":1,"stem_cn":"这些线索能解释那些奇怪的圆点。","explanation_cn":"account for sth,“解释、说明”,固定介词 for。✓ account for the strange dots. ✗ with / of / at:account 搭配 for。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp4','choice','{"stem":"\"There is a relation ___ the paintings and the markings.\"(两者之间用哪个)","options":["between","beside","among","within"],"answer_index":0,"stem_cn":"壁画与记号之间存在某种联系。","explanation_cn":"两者(A 和 B)之间用 between。✓ a relation between the paintings and the markings. ✗ among(三者以上)/ within / beside:两者之间用 between。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp4','choice','{"stem":"\"The markings were found ___ many ancient tribes.\"(三者以上之中用哪个)","options":["within","between","beside","among"],"answer_index":3,"stem_cn":"这些记号在许多古代部落中都有发现。","explanation_cn":"三者或更多之中用 among。✓ found among many ancient tribes. ✗ between(两者)/ beside / within:多者之中用 among。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp4','choice','{"stem":"\"Share the food ___ the two of you.\"(两个人之间\"分\"用哪个)","options":["between","among","along","across"],"answer_index":0,"stem_cn":"这些食物你们俩分了吧。","explanation_cn":"两个人之间“分”用 between。✓ Share it between the two of you. ✗ among(三者以上)/ along / across:两者之间用 between。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp5','choice','{"stem":"\"The evidence seems ___ indicate that the assumption is wrong.\"(seem + 不定式)","options":["of","to","that","for"],"answer_index":1,"stem_cn":"证据似乎表明这个假设是错的。","explanation_cn":"seem 后接不定式 to do。✓ seems to indicate that… ✗ that / for / of:seem 后接 to do。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp5','choice','{"stem":"\"The markings ___ to be a primitive calendar.\"(\"原来是、证明是\"用 prove ___)","options":["proved","appeared as","looked","seemed that"],"answer_index":0,"stem_cn":"这些记号原来是一种原始的历法。","explanation_cn":"“原来是、证明是”用 prove to be。✓ The markings proved to be a calendar. ✗ seemed that / appeared as / looked:用 prove to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp5','choice','{"stem":"\"The old theory ___ to be incorrect.\"(\"看来、显得…\",后接 to be)","options":["seems as","appears that","looks as","appears"],"answer_index":3,"stem_cn":"那个旧理论看来是错的。","explanation_cn":"“看来、显得”用 appear to be。✓ The theory appears to be incorrect. ✗ appears that(应接 it appears that)/ seems as / looks as:用 appears to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp6','choice','{"stem":"\"To work something out by reasoning from clues is to ___ it.\"(\"推断、推理\"用哪个词)","options":["deduce","ignore","forget","copy"],"answer_index":0,"stem_cn":"靠线索推理得出结论。","explanation_cn":"靠线索推理得出结论是 deduce(推断)。✓ deduce what he can from clues. ✗ ignore 忽视;✗ forget 忘记;✗ copy 复制——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp6','choice','{"stem":"\"When there are only a few clues available, they are ___.\"(\"不足的、贫乏的\"用哪个词)","options":["heavy","scanty","bright","plentiful"],"answer_index":1,"stem_cn":"只有很少几条线索,很贫乏。","explanation_cn":"线索很少、不足是 scanty(贫乏的)。✓ a few scanty clues. ✗ plentiful 充足;✗ heavy 沉;✗ bright 亮——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',5,'am3_l38_gp6','choice','{"stem":"\"Something small and unimportant is ___.\"(\"不重要的\"用哪个词)","options":["huge","urgent","precious","insignificant"],"answer_index":3,"stem_cn":"微不足道、不重要的东西。","explanation_cn":"微不足道、不重要的是 insignificant。✓ seemingly insignificant remains. ✗ precious 珍贵;✗ huge 巨大;✗ urgent 紧急——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"calendar 的意思是:","options":["账单","地图","历法,日历","字典"],"answer_index":2,"explanation_cn":"calendar = 历法、日历。✓ a primitive kind of calendar 一种原始的历法。\n顺带记:地图 = map;字典 = dictionary;账单 = bill."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"historian 的意思是:","options":["农民","医生","画家","历史学家"],"answer_index":3,"explanation_cn":"historian = 历史学家。✓ future historians 未来的历史学家。\n顺带记:画家 = painter;医生 = doctor;农民 = farmer."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"unique 的意思是:","options":["廉价的","普通的","独特的,无与伦比的","常见的"],"answer_index":2,"explanation_cn":"unique = 独特的、无与伦比的。✓ in a unique position 处于独特的位置。\n顺带记:普通的 = ordinary;常见的 = common;廉价的 = cheap."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"bewilder 的意思是:","options":["使平静","使迷惑","使疲倦","使高兴"],"answer_index":1,"explanation_cn":"bewilder = 使迷惑。✓ a bewildering amount of information 令人眼花缭乱的信息。\n顺带记:使高兴 = please;使疲倦 = tire;使平静 = calm."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"advent 的意思是:","options":["出现,到来","失败","结束","消失"],"answer_index":0,"explanation_cn":"advent = 出现、到来。✓ the advent of agriculture 农业的出现。\n顺带记:消失 = disappearance;结束 = end;失败 = failure."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',6,NULL,'choice','{"stem":"ivory 的意思是:","options":["石头","黄金","木头","象牙(制品)"],"answer_index":3,"explanation_cn":"ivory = 象牙(制品)。✓ the ivory tusks of mammoths 猛犸的象牙。\n顺带记:木头 = wood;石头 = stone;黄金 = gold."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',7,NULL,'cloze','{"stem":"第 1 空","context":"Historians have long been ___1___ by dots and lines engraved on bones and ivory. These markings have ___2___ found all over the world. Recent evidence seems ___3___ show that they form a primitive calendar. There may be a definite relation ___4___ ancient cave paintings and these markings.","blank_no":1,"options":["puzzled","puzzling","puzzle","to puzzle"],"answer_index":0,"explanation_cn":"have been + 过去分词,“一直被弄糊涂”。✓ Historians have long been puzzled by dots and lines."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',7,NULL,'cloze','{"stem":"第 2 空","context":"Historians have long been ___1___ by dots and lines engraved on bones and ivory. These markings have ___2___ found all over the world. Recent evidence seems ___3___ show that they form a primitive calendar. There may be a definite relation ___4___ ancient cave paintings and these markings.","blank_no":2,"options":["been","being","be","was"],"answer_index":0,"explanation_cn":"现在完成时的被动 have been + 过去分词。✓ These markings have been found all over the world."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',7,NULL,'cloze','{"stem":"第 3 空","context":"Historians have long been ___1___ by dots and lines engraved on bones and ivory. These markings have ___2___ found all over the world. Recent evidence seems ___3___ show that they form a primitive calendar. There may be a definite relation ___4___ ancient cave paintings and these markings.","blank_no":3,"options":["to","that","for","of"],"answer_index":0,"explanation_cn":"seem 后接不定式 to do。✓ Recent evidence seems to show that…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',7,NULL,'cloze','{"stem":"第 4 空","context":"Historians have long been ___1___ by dots and lines engraved on bones and ivory. These markings have ___2___ found all over the world. Recent evidence seems ___3___ show that they form a primitive calendar. There may be a definite relation ___4___ ancient cave paintings and these markings.","blank_no":4,"options":["between","among","within","beside"],"answer_index":0,"explanation_cn":"两者(paintings 和 markings)之间用 between。✓ a definite relation between cave paintings and these markings."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',8,NULL,'choice','{"stem":"What had historians long assumed about calendars?","options":["That nomads never used them","That they came from the moon","That they began with the advent of agriculture","That they were invented last century"],"answer_index":2,"explanation_cn":"课文说 historians have assumed that calendars came into being with the advent of agriculture——历史学家一直以为历法随农业出现而产生。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',8,NULL,'choice','{"stem":"What were the mysterious markings finally found to be?","options":["A form of money","A children''s game","A map of rivers","A primitive kind of calendar"],"answer_index":3,"explanation_cn":"课文说 It is, in fact, a primitive kind of calendar——这些记号其实是一种原始历法。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',8,NULL,'choice','{"stem":"How did historians manage to read the code?","options":["By correlating markings made around the world","By asking modern nomads","By reading old books","By simply guessing"],"answer_index":0,"explanation_cn":"课文说 By correlating markings made in various parts of the world, historians have been able to read this difficult code——靠比对世界各地的记号解读了密码。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',9,NULL,'choice','{"stem":"你想说\"历史学家面对着一项极难的任务\"(be faced with):","options":["The historian is faced to a very difficult task.","The historian is faced of a very difficult task.","The historian is faced for a very difficult task.","The historian is faced with a very difficult task."],"answer_index":3,"explanation_cn":"be faced with sth,“面对…”,固定介词 with。✓ The historian is faced with a very difficult task. 场合:说某人面对某项任务或困难。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',9,NULL,'choice','{"stem":"你想说\"壁画与记号之间存在某种联系\"(between):","options":["There is a relation beside the paintings and the markings.","There is a relation between the paintings and the markings.","There is a relation within the paintings and the markings.","There is a relation among the paintings and the markings."],"answer_index":1,"explanation_cn":"两者(A 和 B)之间用 between。✓ There is a relation between the paintings and the markings. 场合:说两样东西之间的联系。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',9,NULL,'choice','{"stem":"你想说\"证据似乎表明这个假设是错的\"(seem to do):","options":["The evidence seems indicating that the assumption is wrong.","The evidence seems that indicate the assumption is wrong.","The evidence seems to indicate that the assumption is wrong.","The evidence seems to indicated that the assumption is wrong."],"answer_index":2,"explanation_cn":"seem 后接不定式 to do。✓ The evidence seems to indicate that the assumption is wrong. 场合:说某事“似乎表明…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"calendar 的意思是:","options":["字典","地图","账单","历法,日历"],"answer_index":3,"explanation_cn":"calendar = 历法、日历。✓ a primitive kind of calendar."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"deduce 的意思是:","options":["复制","推断,推理","忽视","忘记"],"answer_index":1,"explanation_cn":"deduce = 推断、推理。✓ deduce what he can from clues 从线索里推断。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"\"The dots have ___ engraved on bones and ivory.\"(现在完成时的被动,填 have 和过去分词中间的那个词)","options":["being","be","was","been"],"answer_index":3,"stem_cn":"这些小圆点被刻在骨头和象牙上。","explanation_cn":"现在完成时的被动 have been + 过去分词。✓ The dots have been engraved on bones and ivory. ✗ being / be / was:现在完成被动用 been + 过去分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"\"There is a relation ___ the paintings and the markings.\"(两者之间用哪个)","options":["within","between","among","beside"],"answer_index":1,"stem_cn":"壁画与记号之间存在某种联系。","explanation_cn":"两者(A 和 B)之间用 between。✓ a relation between the paintings and the markings. ✗ among(三者以上)/ within / beside:两者之间用 between。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"\"come into being\" 的意思是:","options":["成为现实","变得无聊","产生、形成","走进屋子"],"answer_index":2,"explanation_cn":"come into being = 产生、形成。✓ calendars came into being 历法产生了。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"\"shed light on\" 的意思是:","options":["点亮灯光","使…更清楚、有助于了解","洒下阳光","减轻重量"],"answer_index":1,"explanation_cn":"shed light on = 使…更清楚、有助于了解。✓ shed light on the history of early man 让人更了解早期人类。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"Why will future historians be in a unique position?","options":["They will have films, videos, and other rich records of our times","They will have no evidence at all","They will only read books","They will guess everything"],"answer_index":0,"passage":"Future historians will be in a unique position when they come to record the history of our own times. They will hardly know which facts to select from the great mass of evidence that steadily accumulates. What is more, they will not have to rely solely on the written word. Films, videos, CDs, and CD-ROMs are just some of the bewildering amount of information they will have. They will be able, as it were, to see and hear us in action. But the historian who tries to reconstruct the distant past is always faced with a difficult task. He must deduce what he can from the few scanty clues available. Even seemingly insignificant remains can shed light on the history of early man. Up to now, historians have assumed that calendars came into being with the advent of agriculture, for man was then faced with a real need to understand something about the seasons. Recent scientific evidence seems to indicate that this assumption is incorrect. Historians have long been puzzled by dots, lines, and symbols that have been engraved on walls, bones, and the ivory tusks of mammoths. The nomads who made these markings lived by hunting and fishing during the last Ice Age, which began about 35,000 B.C. and ended about 10,000 B.C. By correlating markings made in various parts of the world, historians have been able to read this difficult code. They have found that it is connected with the passage of days and the phases of the moon. It is, in fact, a primitive kind of calendar. It has long been known that the scenes painted on cave walls were not simply a form of artistic expression. They had a definite meaning, for they were as near as early man could get to writing. It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them. It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","explanation_cn":"课文说 Films, videos, CDs, and CD-ROMs are just some of the bewildering amount of information they will have——未来历史学家拥有丰富的影像资料,所以处境独特。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"What do the ancient markings show about early man?","options":["He ignored the moon","He could already write fluently","He was trying to understand the seasons far earlier than supposed","He never hunted"],"answer_index":2,"passage":"Future historians will be in a unique position when they come to record the history of our own times. They will hardly know which facts to select from the great mass of evidence that steadily accumulates. What is more, they will not have to rely solely on the written word. Films, videos, CDs, and CD-ROMs are just some of the bewildering amount of information they will have. They will be able, as it were, to see and hear us in action. But the historian who tries to reconstruct the distant past is always faced with a difficult task. He must deduce what he can from the few scanty clues available. Even seemingly insignificant remains can shed light on the history of early man. Up to now, historians have assumed that calendars came into being with the advent of agriculture, for man was then faced with a real need to understand something about the seasons. Recent scientific evidence seems to indicate that this assumption is incorrect. Historians have long been puzzled by dots, lines, and symbols that have been engraved on walls, bones, and the ivory tusks of mammoths. The nomads who made these markings lived by hunting and fishing during the last Ice Age, which began about 35,000 B.C. and ended about 10,000 B.C. By correlating markings made in various parts of the world, historians have been able to read this difficult code. They have found that it is connected with the passage of days and the phases of the moon. It is, in fact, a primitive kind of calendar. It has long been known that the scenes painted on cave walls were not simply a form of artistic expression. They had a definite meaning, for they were as near as early man could get to writing. It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them. It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","explanation_cn":"课文说 man was making a real effort to understand the seasons 20,000 years earlier than has been supposed——早期人类比人们设想的早两万年就在努力了解季节。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"Who made the mysterious markings?","options":["Sailors","Farmers of today","Modern scientists","Nomads who lived by hunting and fishing in the Ice Age"],"answer_index":3,"audio":"Future historians will be in a unique position when they come to record the history of our own times. They will hardly know which facts to select from the great mass of evidence that steadily accumulates. What is more, they will not have to rely solely on the written word. Films, videos, CDs, and CD-ROMs are just some of the bewildering amount of information they will have. They will be able, as it were, to see and hear us in action. But the historian who tries to reconstruct the distant past is always faced with a difficult task. He must deduce what he can from the few scanty clues available. Even seemingly insignificant remains can shed light on the history of early man. Up to now, historians have assumed that calendars came into being with the advent of agriculture, for man was then faced with a real need to understand something about the seasons. Recent scientific evidence seems to indicate that this assumption is incorrect. Historians have long been puzzled by dots, lines, and symbols that have been engraved on walls, bones, and the ivory tusks of mammoths. The nomads who made these markings lived by hunting and fishing during the last Ice Age, which began about 35,000 B.C. and ended about 10,000 B.C. By correlating markings made in various parts of the world, historians have been able to read this difficult code. They have found that it is connected with the passage of days and the phases of the moon. It is, in fact, a primitive kind of calendar. It has long been known that the scenes painted on cave walls were not simply a form of artistic expression. They had a definite meaning, for they were as near as early man could get to writing. It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them. It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","explanation_cn":"课文说 The nomads who made these markings lived by hunting and fishing during the last Ice Age——留下记号的是冰河时代靠打猎捕鱼为生的游牧人。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l38',10,NULL,'choice','{"stem":"What were the markings connected with?","options":["The passage of days and the phases of the moon","The weather only","The price of food","The size of tribes"],"answer_index":0,"audio":"Future historians will be in a unique position when they come to record the history of our own times. They will hardly know which facts to select from the great mass of evidence that steadily accumulates. What is more, they will not have to rely solely on the written word. Films, videos, CDs, and CD-ROMs are just some of the bewildering amount of information they will have. They will be able, as it were, to see and hear us in action. But the historian who tries to reconstruct the distant past is always faced with a difficult task. He must deduce what he can from the few scanty clues available. Even seemingly insignificant remains can shed light on the history of early man. Up to now, historians have assumed that calendars came into being with the advent of agriculture, for man was then faced with a real need to understand something about the seasons. Recent scientific evidence seems to indicate that this assumption is incorrect. Historians have long been puzzled by dots, lines, and symbols that have been engraved on walls, bones, and the ivory tusks of mammoths. The nomads who made these markings lived by hunting and fishing during the last Ice Age, which began about 35,000 B.C. and ended about 10,000 B.C. By correlating markings made in various parts of the world, historians have been able to read this difficult code. They have found that it is connected with the passage of days and the phases of the moon. It is, in fact, a primitive kind of calendar. It has long been known that the scenes painted on cave walls were not simply a form of artistic expression. They had a definite meaning, for they were as near as early man could get to writing. It is possible that there is a definite relation between these paintings and the markings that sometimes accompany them. It seems that man was making a real effort to understand the seasons 20,000 years earlier than has been supposed.","explanation_cn":"课文说 it is connected with the passage of days and the phases of the moon——这些记号与日子流逝和月相有关。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l39',3,8,39,'Nothing to Worry About','没什么好担心的','be able to(各时态“能/得以”)、manage to(设法做成·强调克服困难)、could 与 was able to/managed to 的区别(过去某次成功不用 could)、can/could 表一般能力、过去进行做背景+一般过去推进情节(按 Aaron 净化包生产·不读源 PDF:自信司机横穿崎岖平原、设法躲过各种障碍,最后车停不是出事而是没油了·喜剧内核保留,惊险措辞已放缓;美式化 gas/gas tank)','我的朋友汤姆是个自信的司机,再崎岖的路也从不慌张。去年夏天,我们开着他那辆旧车,得以横穿一片宽阔多石的平原。“没什么好担心的,”他说;可我还是低估了这段路有多颠。车子一路颠簸,车轮卷起松散的沙子和小石子。汤姆设法绕开了每一块大圆石,车速几乎没怎么减。到了一段松软的地面,他挂上低速挡,还能让车稳稳往前开。有一次为了躲开一道浅沟,他让车轮跨骑在浅沟两侧,径直开了过去。前面还有几处障碍,但汤姆每次都设法找到一条安全的路。“瞧?咱们什么都能应付,”他拍着方向盘笑道。可就在半路上,发动机不祥地咳了一声,车慢慢停了下来。任我们怎么使劲,也没能把它重新发动起来。原来真的没什么好担心的——我们只不过是把油开光了!','{"q":"Listen and answer — What was the difference between Tom''s behavior and the others''?","options":["Tom stayed completely calm and was never worried","Tom refused to drive at all","Tom drove painfully slowly","Tom got out and walked"],"answer_index":0}'::jsonb,'{"title":"be able to / manage to / could vs was able to / can 表能力 / 过去进行做背景","intro":"①be able to 各时态表“能、得以”:were able to(过去)、was able to、will be able to(将来)。②manage to do=设法做成(强调克服了困难)。③过去某一次“终于做成”用 was able to 或 managed to,不用 could。④can/could 表一般能力:can(现在)、could(过去一贯)。⑤讲故事时,过去进行(was/were doing)做背景,一般过去时推进情节。","table":{"headers":["用法","意思","例子"],"rows":[["be able to（各时态）","能/得以","we were able to cross"],["manage to do","设法做成","he managed to steer around"],["could vs was able to","一次成功不用 could","he was able to start the car"],["过去进行做背景","正在…时","as we were bouncing along"]]},"specialRules":[{"rule":"过去某一次“终于做成、成功做到”用 was/were able to 或 managed to,不用 could;could 多表“一贯的能力”。","mark":"was able to ≠ could"},{"rule":"manage to do 强调“克服困难后设法做成”,比单纯 be able to 更有“不容易”的意味。","mark":"manage to do"},{"rule":"美式:gas(英式 petrol)、gas tank(英式 petrol tank)、hood(英式 bonnet)、trunk(英式 boot)。本课已按美语写。","mark":"gas / hood / trunk"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l39',1,NULL,'My friend Tom is a confident driver who is never perturbed by a rough road. Last summer, we were able to cross a wide, rocky plain in his old car. ''There''s nothing to worry about,'' he said, though I had underestimated just how bumpy the drive would be.','我的朋友汤姆是个自信的司机,再崎岖的路也从不慌张。去年夏天,我们开着他那辆旧车,得以横穿一片宽阔多石的平原。“没什么好担心的,”他说;可我还是低估了这段路有多颠。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l39',2,NULL,'As we were bouncing along the track, the wheels scooped up loose sand and small stones. Tom managed to steer around every boulder without slowing down much. When we reached a stretch of soft ground, he shifted into a low gear and was able to keep the car moving.','车子一路颠簸,车轮卷起松散的沙子和小石子。汤姆设法绕开了每一块大圆石,车速几乎没怎么减。到了一段松软的地面,他挂上低速挡,还能让车稳稳往前开。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l39',3,NULL,'Once, to avoid a shallow rut, he kept the wheels astride it and drove straight on. A few more obstacles lay ahead, but Tom managed to find a safe path each time. ''See? We can handle anything,'' he laughed, patting the wheel.','有一次为了躲开一道浅沟,他让车轮跨骑在浅沟两侧,径直开了过去。前面还有几处障碍,但汤姆每次都设法找到一条安全的路。“瞧?咱们什么都能应付,”他拍着方向盘笑道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l39',4,NULL,'Then, halfway across, the engine coughed ominously and the car slowly rolled to a stop. We weren''t able to start it again, no matter how hard we tried.','可就在半路上,发动机不祥地咳了一声,车慢慢停了下来。任我们怎么使劲,也没能把它重新发动起来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l39',5,NULL,'It turned out there was nothing to worry about after all — we had simply run out of gas!','原来真的没什么好担心的——我们只不过是把油开光了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
