INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l39','nothing to worry about','',NULL,'/ˈnʌθɪŋ tə ˈwɜːri əˈbaʊt/','There''s nothing to worry about.','没什么好担心的。','Relax — there''s nothing to worry about.','放轻松,没什么好担心的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l39','run out of','',NULL,'/rʌn aʊt əv/','We had run out of gas.','我们把油开光了。','They ran out of time.','他们没时间了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l39','in low gear','',NULL,'/ɪn loʊ ɡɪr/','He drove in low gear over the sand.','他挂低速挡开过沙地。','Shift into low gear on the hill.','上坡时换到低速挡。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l39','manage to','',NULL,'/ˈmænɪdʒ tə/','He managed to avoid the rock.','他设法避开了那块石头。','She managed to finish on time.','她设法按时完成了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp1','choice','{"stem":"\"We ___ able to cross the rocky plain last summer.\"(过去\"得以、能够\",填 be 的过去式)","options":["will be","were","being","are"],"answer_index":1,"stem_cn":"去年夏天我们得以横穿那片多石的平原。","explanation_cn":"be able to 的过去式,主语复数用 were able to。✓ We were able to cross the plain. ✗ are(现在)/ will be(将来)/ being:过去用 were able to。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp1','choice','{"stem":"\"In soft ground he ___ able to keep the car moving.\"(过去某次\"能够\",主语单数)","options":["was","being","is","were"],"answer_index":0,"stem_cn":"在松软的地面上,他还能让车继续前进。","explanation_cn":"be able to 的过去式,主语单数用 was able to。✓ he was able to keep the car moving. ✗ were(复数)/ is(现在)/ being:单数过去用 was able to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp1','choice','{"stem":"\"With a better car, we ___ able to cross faster next time.\"(将来\"将能够\")","options":["are","being","will be","were"],"answer_index":2,"stem_cn":"换辆好车,下次我们就能更快穿过去。","explanation_cn":"be able to 的将来式用 will be able to。✓ we will be able to cross faster next time. ✗ are(现在)/ were(过去)/ being:将来用 will be able to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp2','choice','{"stem":"\"Tom ___ to steer around every boulder.\"(\"设法做成(克服困难)\"用 ___ to do)","options":["ought","managed","could","must"],"answer_index":1,"stem_cn":"汤姆设法绕开了每一块大圆石。","explanation_cn":"“设法做成(克服困难)”用 manage to do。✓ Tom managed to steer around every boulder. ✗ could(一贯能力)/ must / ought:设法做成用 managed to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp2','choice','{"stem":"\"Despite the sand, he ___ to find a safe path.\"(\"设法找到\"用 ___ to do)","options":["promised","wanted","refused","managed"],"answer_index":3,"stem_cn":"尽管有沙子,他还是设法找到了一条安全的路。","explanation_cn":"“设法找到”用 manage to do。✓ managed to find a safe path. ✗ wanted / refused / promised:设法做成用 managed to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp2','choice','{"stem":"\"We ___ to reach the village before dark.\"(\"设法赶到\"用 ___ to do)","options":["hoped","agreed","managed","decided"],"answer_index":2,"stem_cn":"我们设法在天黑前赶到了村子。","explanation_cn":"“设法赶到”用 manage to do。✓ managed to reach the village. ✗ hoped / agreed / decided:设法做成用 managed to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp3','choice','{"stem":"\"After many tries, he finally ___ to start the car.\"(某一次终于\"做成\",不用 could)","options":["was able","could","could to","can"],"answer_index":0,"stem_cn":"试了很多次,他终于把车发动起来了。","explanation_cn":"某一次终于“做成”用 was able to(或 managed to),不用 could。✓ he finally was able to start the car. ✗ could(不用于一次成功)/ can / could to:一次成功用 was able to。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp3','choice','{"stem":"\"That day we ___ to cross the plain safely.\"(某一次成功\"做到\",用 ___ to)","options":["could","would","can","managed"],"answer_index":3,"stem_cn":"那天我们平安穿过了平原。","explanation_cn":"某一次成功“做到”用 managed to(或 was able to)。✓ we managed to cross the plain. ✗ could(不用于一次成功)/ can / would:一次成功用 managed to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp3','choice','{"stem":"\"He ___ swim across the river that morning.\"(某一次成功游过去,别用 could,用哪个)","options":["can","could have","was able to","could"],"answer_index":2,"stem_cn":"那天早上他成功游过了河。","explanation_cn":"某一次成功游过去,用 was able to,不用 could。✓ he was able to swim across. ✗ could(不用于一次成功)/ can / could have:一次成功用 was able to。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp4','choice','{"stem":"\"Tom is a good driver; he ___ handle any road.\"(表示现在的一般能力)","options":["can","managed","could","was able"],"answer_index":0,"stem_cn":"汤姆车技好,什么路都能应付。","explanation_cn":"表示现在的一般能力用 can。✓ he can handle any road. ✗ could(过去)/ was able / managed:现在能力用 can。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp4','choice','{"stem":"\"When he was young, he ___ drive for hours without tiring.\"(表示过去的一般能力)","options":["can","could","was able","managed"],"answer_index":1,"stem_cn":"他年轻时能连开好几个小时也不累。","explanation_cn":"表示过去的一贯能力用 could。✓ he could drive for hours. ✗ can(现在)/ managed(一次)/ was able(常指一次):过去一贯能力用 could。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp4','choice','{"stem":"\"___ you drive a car with a manual gear?\"(问对方\"会不会、能不能\")","options":["Can","Were","Managed","Did"],"answer_index":0,"stem_cn":"你会开手动挡的车吗?","explanation_cn":"问“会不会、能不能”用 Can you …?✓ Can you drive a manual? ✗ Did / Managed / Were:问能力用 Can。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp5','choice','{"stem":"\"As we ___ along the track, the wheels scooped up sand.\"(表当时\"正在进行\"的背景,用过去进行)","options":["bounce","have bounced","bounced","were bouncing"],"answer_index":3,"stem_cn":"我们正沿着车道颠簸时,车轮卷起了沙子。","explanation_cn":"表当时“正在进行”的背景,用过去进行 were doing。✓ As we were bouncing along… ✗ bounced / bounce / have bounced:背景用过去进行。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp5','choice','{"stem":"\"While Tom ___ , the engine suddenly coughed.\"(\"正在开车\"时被打断,用过去进行)","options":["was driving","had driven","drives","drove"],"answer_index":0,"stem_cn":"汤姆正开着车,发动机突然咳了一声。","explanation_cn":"“正在开车”时被突然打断,用过去进行 was doing。✓ While Tom was driving, the engine coughed. ✗ drove / drives / had driven:被打断的背景用过去进行。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp5','choice','{"stem":"\"The car ___ to a stop in the middle of the plain.\"(推进情节的动作,用一般过去时)","options":["rolls","has rolled","rolled","was rolling"],"answer_index":2,"stem_cn":"车在平原中央停了下来。","explanation_cn":"推进情节的动作用一般过去时。✓ The car rolled to a stop. ✗ was rolling(进行)/ rolls / has rolled:推进情节用一般过去。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp6','choice','{"stem":"\"A calm person who is not upset by trouble is not easily ___.\"(\"使不安\"用哪个词)","options":["tired","perturbed","amused","pleased"],"answer_index":1,"stem_cn":"遇事沉着、不慌的人不易被扰乱。","explanation_cn":"“使不安”用 perturb;沉着的人不易被 perturbed。✓ never perturbed by a rough road. ✗ pleased 高兴;✗ amused 逗乐;✗ tired 累——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp6','choice','{"stem":"\"To think something is smaller or easier than it really is is to ___ it.\"(\"低估\"用哪个词)","options":["underestimate","admire","ignore","overpraise"],"answer_index":0,"stem_cn":"把事情想得太小、太容易就是低估。","explanation_cn":"“把事情想得太小、太容易”是 underestimate(低估)。✓ I had underestimated the drive. ✗ overpraise 过誉;✗ admire 欣赏;✗ ignore 忽视——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',5,'am3_l39_gp6','choice','{"stem":"\"When the engine coughed ___, we felt something was wrong.\"(\"不祥地\"用哪个词)","options":["quietly","cheerfully","brightly","ominously"],"answer_index":3,"stem_cn":"发动机不祥地咳了一声,我们觉得不妙。","explanation_cn":"“不祥地”用 ominously。✓ the engine coughed ominously. ✗ cheerfully 欢快;✗ quietly 安静;✗ brightly 明亮——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"rough 的意思是:","options":["平滑的","明亮的","崎岖不平的","柔软的"],"answer_index":2,"explanation_cn":"rough = 崎岖不平的。✓ a rough road 崎岖的路。\n顺带记:平滑的 = smooth;柔软的 = soft;明亮的 = bright."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"boulder 的意思是:","options":["沙子","水坑","树枝","大圆石"],"answer_index":3,"explanation_cn":"boulder = 大圆石。✓ steer around every boulder 绕开每块大圆石。\n顺带记:沙子 = sand;树枝 = branch;水坑 = puddle."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"obstacle 的意思是:","options":["障碍","礼物","工具","出口"],"answer_index":0,"explanation_cn":"obstacle = 障碍。✓ a few more obstacles lay ahead 前面还有几处障碍。\n顺带记:出口 = exit;礼物 = gift;工具 = tool."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"gear 的意思是:","options":["方向盘","(汽车)挡位","车灯","喇叭"],"answer_index":1,"explanation_cn":"gear = (汽车)挡位。✓ shifted into a low gear 挂上低速挡。\n顺带记:方向盘 = steering wheel;喇叭 = horn;车灯 = headlight."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"stretch 的意思是:","options":["角落","中心","尽头","一段(路程)"],"answer_index":3,"explanation_cn":"stretch = 一段(路程)。✓ a stretch of soft ground 一段松软的地面。\n顺带记:尽头 = end;中心 = center;角落 = corner."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',6,NULL,'choice','{"stem":"confident 的意思是:","options":["自信的","疲惫的","生气的","害羞的"],"answer_index":0,"explanation_cn":"confident = 自信的。✓ a confident driver 自信的司机。\n顺带记:害羞的 = shy;疲惫的 = tired;生气的 = angry."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',7,NULL,'cloze','{"stem":"第 1 空","context":"My friend Tom is a confident driver who is never ___1___ by a rough road. Last summer we ___2___ able to cross a rocky plain in his old car. He ___3___ to steer around every boulder without slowing down. Halfway across, the engine coughed ___4___ and the car stopped — we had simply run out of gas!","blank_no":1,"options":["perturbed","pleased","amused","tired"],"answer_index":0,"explanation_cn":"“使不安”用 perturb;自信的司机不会被 perturbed。✓ never perturbed by a rough road."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',7,NULL,'cloze','{"stem":"第 2 空","context":"My friend Tom is a confident driver who is never ___1___ by a rough road. Last summer we ___2___ able to cross a rocky plain in his old car. He ___3___ to steer around every boulder without slowing down. Halfway across, the engine coughed ___4___ and the car stopped — we had simply run out of gas!","blank_no":2,"options":["were","are","will","being"],"answer_index":0,"explanation_cn":"be able to 的过去式,主语复数用 were able to。✓ we were able to cross a rocky plain."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',7,NULL,'cloze','{"stem":"第 3 空","context":"My friend Tom is a confident driver who is never ___1___ by a rough road. Last summer we ___2___ able to cross a rocky plain in his old car. He ___3___ to steer around every boulder without slowing down. Halfway across, the engine coughed ___4___ and the car stopped — we had simply run out of gas!","blank_no":3,"options":["managed","could","must","ought"],"answer_index":0,"explanation_cn":"“设法做成”用 manage to do。✓ He managed to steer around every boulder."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',7,NULL,'cloze','{"stem":"第 4 空","context":"My friend Tom is a confident driver who is never ___1___ by a rough road. Last summer we ___2___ able to cross a rocky plain in his old car. He ___3___ to steer around every boulder without slowing down. Halfway across, the engine coughed ___4___ and the car stopped — we had simply run out of gas!","blank_no":4,"options":["ominously","cheerfully","softly","brightly"],"answer_index":0,"explanation_cn":"“不祥地”用 ominously。✓ the engine coughed ominously."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',8,NULL,'choice','{"stem":"What kind of driver is Tom?","options":["A very slow driver","A confident one who is never perturbed by rough roads","A nervous beginner","One who hates cars"],"answer_index":1,"explanation_cn":"课文说 Tom is a confident driver who is never perturbed by a rough road——汤姆是个再崎岖的路也不慌的自信司机。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',8,NULL,'choice','{"stem":"How did Tom get past the boulders?","options":["He turned back","He waited for help","He managed to steer around each one","He pushed them aside"],"answer_index":2,"explanation_cn":"课文说 Tom managed to steer around every boulder——他设法绕开每一块大圆石。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',8,NULL,'choice','{"stem":"Why did the car finally stop?","options":["It had simply run out of gas","The engine exploded","A tire burst","It hit a boulder"],"answer_index":0,"explanation_cn":"课文说 It turned out…we had simply run out of gas——原来只是没油了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',9,NULL,'choice','{"stem":"你想说\"汤姆设法绕开了每一块大圆石\"(manage to):","options":["Tom managed steering around every boulder.","Tom managed to steered around every boulder.","Tom was manage to steer around every boulder.","Tom managed to steer around every boulder."],"answer_index":3,"explanation_cn":"“设法做成”用 manage to do(不定式带 to,后接原形)。✓ Tom managed to steer around every boulder. 场合:说某人克服困难做成了某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',9,NULL,'choice','{"stem":"你想说\"那天我们平安穿过了平原\"(was able to,一次成功):","options":["That day we were able to cross the plain safely.","That day we could cross the plain safely.","That day we were able cross the plain safely.","That day we can cross the plain safely."],"answer_index":0,"explanation_cn":"某一次成功“做到”用 was/were able to,不用 could。✓ That day we were able to cross the plain safely. 场合:说某一次终于成功做成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',9,NULL,'choice','{"stem":"你想说\"你会开手动挡的车吗\"(can 表能力):","options":["Are you can drive a car with a manual gear?","Do you can drive a car with a manual gear?","Can you drive a car with a manual gear?","Can you to drive a car with a manual gear?"],"answer_index":2,"explanation_cn":"问“会不会、能不能”用 Can you + 动词原形。✓ Can you drive a car with a manual gear? 场合:询问对方是否有某种能力。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"confident 的意思是:","options":["自信的","疲惫的","害羞的","生气的"],"answer_index":0,"explanation_cn":"confident = 自信的。✓ a confident driver."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"obstacle 的意思是:","options":["礼物","障碍","工具","出口"],"answer_index":1,"explanation_cn":"obstacle = 障碍。✓ a few more obstacles lay ahead."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"\"We ___ able to cross the plain last summer.\"(过去\"得以\",填 be 的过去式)","options":["were","are","will be","being"],"answer_index":0,"stem_cn":"去年夏天我们得以横穿平原。","explanation_cn":"be able to 的过去式,主语复数用 were able to。✓ We were able to cross the plain. ✗ are(现在)/ will be(将来)/ being:过去用 were able to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"\"Tom ___ to steer around every boulder.\"(\"设法做成\"用 ___ to do)","options":["ought","managed","could","must"],"answer_index":1,"stem_cn":"汤姆设法绕开了每一块大圆石。","explanation_cn":"“设法做成”用 manage to do。✓ Tom managed to steer around every boulder. ✗ could(一贯能力)/ must / ought:设法做成用 managed to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"\"run out of\" 的意思是:","options":["追上","甩开","跑出去","用完、耗尽"],"answer_index":3,"explanation_cn":"run out of = 用完、耗尽。✓ we had run out of gas 我们把油开光了。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"\"nothing to worry about\" 的意思是:","options":["无处可去","没什么好担心的","无话可说","无事可做"],"answer_index":1,"explanation_cn":"nothing to worry about = 没什么好担心的。✓ There''s nothing to worry about."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"Why did the writer say there was ''nothing to worry about'' in the end?","options":["They were badly hurt","The car was completely destroyed","The car stopped only because it had run out of gas","They got lost forever"],"answer_index":2,"passage":"My friend Tom is a confident driver who is never perturbed by a rough road. Last summer, we were able to cross a wide, rocky plain in his old car. ''There''s nothing to worry about,'' he said, though I had underestimated just how bumpy the drive would be. As we were bouncing along the track, the wheels scooped up loose sand and small stones. Tom managed to steer around every boulder without slowing down much. When we reached a stretch of soft ground, he shifted into a low gear and was able to keep the car moving. Once, to avoid a shallow rut, he kept the wheels astride it and drove straight on. A few more obstacles lay ahead, but Tom managed to find a safe path each time. ''See? We can handle anything,'' he laughed, patting the wheel. Then, halfway across, the engine coughed ominously and the car slowly rolled to a stop. We weren''t able to start it again, no matter how hard we tried. It turned out there was nothing to worry about after all — we had simply run out of gas!","explanation_cn":"课文说 there was nothing to worry about after all — we had simply run out of gas——车停只是因为没油,没出别的事。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"How did Tom react to the rough road?","options":["He refused to drive","He stayed calm and was never perturbed","He panicked at once","He drove backward"],"answer_index":1,"passage":"My friend Tom is a confident driver who is never perturbed by a rough road. Last summer, we were able to cross a wide, rocky plain in his old car. ''There''s nothing to worry about,'' he said, though I had underestimated just how bumpy the drive would be. As we were bouncing along the track, the wheels scooped up loose sand and small stones. Tom managed to steer around every boulder without slowing down much. When we reached a stretch of soft ground, he shifted into a low gear and was able to keep the car moving. Once, to avoid a shallow rut, he kept the wheels astride it and drove straight on. A few more obstacles lay ahead, but Tom managed to find a safe path each time. ''See? We can handle anything,'' he laughed, patting the wheel. Then, halfway across, the engine coughed ominously and the car slowly rolled to a stop. We weren''t able to start it again, no matter how hard we tried. It turned out there was nothing to worry about after all — we had simply run out of gas!","explanation_cn":"课文说 a confident driver who is never perturbed by a rough road——他始终沉着,从不慌张。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"What did the wheels scoop up as the car bounced along?","options":["Water","Leaves","Snow","Loose sand and small stones"],"answer_index":3,"audio":"My friend Tom is a confident driver who is never perturbed by a rough road. Last summer, we were able to cross a wide, rocky plain in his old car. ''There''s nothing to worry about,'' he said, though I had underestimated just how bumpy the drive would be. As we were bouncing along the track, the wheels scooped up loose sand and small stones. Tom managed to steer around every boulder without slowing down much. When we reached a stretch of soft ground, he shifted into a low gear and was able to keep the car moving. Once, to avoid a shallow rut, he kept the wheels astride it and drove straight on. A few more obstacles lay ahead, but Tom managed to find a safe path each time. ''See? We can handle anything,'' he laughed, patting the wheel. Then, halfway across, the engine coughed ominously and the car slowly rolled to a stop. We weren''t able to start it again, no matter how hard we tried. It turned out there was nothing to worry about after all — we had simply run out of gas!","explanation_cn":"课文说 the wheels scooped up loose sand and small stones——车轮卷起了松散的沙子和小石子。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l39',10,NULL,'choice','{"stem":"What did Tom do when they reached soft ground?","options":["He turned around","He shifted into a low gear","He stopped the car","He got out and pushed"],"answer_index":1,"audio":"My friend Tom is a confident driver who is never perturbed by a rough road. Last summer, we were able to cross a wide, rocky plain in his old car. ''There''s nothing to worry about,'' he said, though I had underestimated just how bumpy the drive would be. As we were bouncing along the track, the wheels scooped up loose sand and small stones. Tom managed to steer around every boulder without slowing down much. When we reached a stretch of soft ground, he shifted into a low gear and was able to keep the car moving. Once, to avoid a shallow rut, he kept the wheels astride it and drove straight on. A few more obstacles lay ahead, but Tom managed to find a safe path each time. ''See? We can handle anything,'' he laughed, patting the wheel. Then, halfway across, the engine coughed ominously and the car slowly rolled to a stop. We weren''t able to start it again, no matter how hard we tried. It turned out there was nothing to worry about after all — we had simply run out of gas!","explanation_cn":"课文说 he shifted into a low gear and was able to keep the car moving——到松软地面时他挂了低速挡。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
